import "./App.css";

function App() {
  return (
    <div className="card">
      <Avatar src="Abdallah.jpg" alt="Abdallah" />
    </div>
  );
}

function Avatar(props) {
  return <img src={props.src} alt={props.alt} className="avatar" />;
}

function Intro() {
  return (
    <div>
      <h1>Abdallah</h1>
      <p>I'm a software engineer and I love to build web applications.</p>
    </div>
  );
}

export default App;
